     1	namespace MaesterCloud.Portal.Models;
     2	
     3	// The portal's roadmap contract. Endpoint-specific, like every portal DTO:
     4	// no author keys, customer ids, operator names, moderation reasons or
     5	// pre-edit text ever cross this boundary - those columns exist only for
     6	// Kermit.
     7	
     8	public sealed record PortalRoadmapPost(
     9	    string Id,
    10	    // feature | suggestion
    11	    string Kind,
    12	    string Title,
    13	    string Summary,
    14	    string Area,
    15	    // feature: planned | progress | done; suggestion: suggested
    16	    string Status,
    17	    int Progress,
    18	    string Release,
    19	    DateTimeOffset? ShippedAt,
    20	    DateTimeOffset CreatedAt,
    21	    // Suggestions only; null for features.
    22	    string? AuthorName,
    23	    // Suggestions only; null for features and when the customer has none.
    24	    string? AuthorCompany,
    25	    bool EditedByTeam,
    26	    // Suggestions linked to a visible feature; null otherwise.
    27	    string? LinkedFeatureId,
    28	    int Votes,
    29	    bool Voted,
    30	    int CommentCount,
    31	    int SuggestionCount);
    32	
    33	public sealed record PortalRoadmapComment(
    34	    string Id,
    35	    // comment | event
    36	    string Kind,
    37	    string? Text,
    38	    string? AuthorName,
    39	    string? AuthorCompany,
    40	    bool Team,
    41	    bool Edited,
    42	    bool Hidden,
    43	    DateTimeOffset CreatedAt);
    44	
    45	public sealed record PortalRoadmapDetail(
    46	    PortalRoadmapPost Post,
    47	    string Description,
    48	    int DirectVotes,
    49	    IReadOnlyList<PortalRoadmapComment> Comments,
    50	    IReadOnlyList<PortalRoadmapPost> LinkedSuggestions,
    51	    PortalRoadmapPost? LinkedFeature);
    52	
    53	public sealed record PortalRoadmapListResponse(IReadOnlyList<PortalRoadmapPost> Posts);
    54	
    55	public sealed record PortalRoadmapSuggestionRequest(string? Title, string? Area, string? Description);
    56	
    57	public sealed record PortalRoadmapCommentRequest(string? Text);
