     1	namespace MaesterCloud.Portal.Services;
     2	
     3	/// <summary>
     4	/// Table and column names of the shared roadmap tables. The portal writes
     5	/// customer suggestions, votes and comments; Kermit writes features and
     6	/// moderation; the signup API's public /api/roadmap reads them. The planes
     7	/// share no code, so each re-declares these names - keep them EXACT, a sync
     8	/// test pins Kermit's copy against this one.
     9	/// </summary>
    10	public static class RoadmapColumns
    11	{
    12	    public const string PostsTable = "RoadmapPosts";
    13	    public const string VotesTable = "RoadmapVotes";
    14	    public const string CommentsTable = "RoadmapComments";
    15	
    16	    /// <summary>Every RoadmapPosts row lives in this one partition; RowKey = post id.</summary>
    17	    public const string PostsPartition = "posts";
    18	
    19	    /// <summary>
    20	    /// RoadmapVotes index rows: PartitionKey = this prefix + voter key, RowKey
    21	    /// = post id. One per vote, beside the vote row itself, so "which posts
    22	    /// did this person vote for" is a single partition read.
    23	    /// </summary>
    24	    public const string VoterPartitionPrefix = "voter:";
    25	
    26	    public const string KindFeature = "feature";
    27	    public const string KindSuggestion = "suggestion";
    28	    public const string KindComment = "comment";
    29	    public const string KindEvent = "event";
    30	
    31	    public const string StatusPlanned = "planned";
    32	    public const string StatusProgress = "progress";
    33	    public const string StatusDone = "done";
    34	
    35	    /// <summary>RoadmapPosts: PartitionKey "posts", RowKey = post id.</summary>
    36	    public static class Posts
    37	    {
    38	        public const string Kind = "Kind";
    39	        public const string Title = "Title";
    40	        public const string Summary = "Summary";
    41	        public const string Description = "Description";
    42	        public const string Area = "Area";
    43	        public const string Status = "Status";
    44	        public const string Progress = "Progress";
    45	        public const string Release = "Release";
    46	        public const string ShippedAt = "ShippedAt";
    47	        public const string Hidden = "Hidden";
    48	        public const string LinkedFeatureId = "LinkedFeatureId";
    49	        public const string AuthorName = "AuthorName";
    50	        public const string AuthorCompany = "AuthorCompany";
    51	        public const string AuthorKey = "AuthorKey";
    52	        public const string AuthorCustomerId = "AuthorCustomerId";
    53	        public const string EditedByTeam = "EditedByTeam";
    54	        public const string CreatedAt = "CreatedAt";
    55	        public const string UpdatedAt = "UpdatedAt";
    56	        public const string UpdatedBy = "UpdatedBy";
    57	
    58	        // Tallies kept on the row by whichever plane changes them, so a
    59	        // board read never scans RoadmapVotes or RoadmapComments.
    60	        // VoteCount: unique voters (a feature counts its linked suggestions'
    61	        // voters too). CommentCount: visible comments, events excluded.
    62	        public const string VoteCount = "VoteCount";
    63	        public const string CommentCount = "CommentCount";
    64	    }
    65	
    66	    /// <summary>RoadmapVotes: PartitionKey = post id, RowKey = voter key (PortalIdentity.StableKey).</summary>
    67	    public static class Votes
    68	    {
    69	        public const string CustomerId = "CustomerId";
    70	        public const string CreatedAt = "CreatedAt";
    71	    }
    72	
    73	    /// <summary>RoadmapComments: PartitionKey = post id, RowKey = comment id.</summary>
    74	    public static class Comments
    75	    {
    76	        public const string Kind = "Kind";
    77	        public const string Text = "Text";
    78	        public const string AuthorName = "AuthorName";
    79	        public const string AuthorCompany = "AuthorCompany";
    80	        public const string AuthorKey = "AuthorKey";
    81	        public const string CustomerId = "CustomerId";
    82	        public const string Team = "Team";
    83	        public const string Actor = "Actor";
    84	        public const string Hidden = "Hidden";
    85	        public const string HiddenReason = "HiddenReason";
    86	        public const string Edited = "Edited";
    87	        public const string OriginalText = "OriginalText";
    88	        public const string CreatedAt = "CreatedAt";
    89	    }
    90	}

