     6	namespace MaesterCloud.Portal.Endpoints;
     7	
     8	/// <summary>
     9	/// The customer roadmap: read the board, vote, suggest and comment. Every
    10	/// route resolves the caller's profile with the same strict rule as billing
    11	/// and users (one constant 403), so only a signed-in customer with a service
    12	/// can take part; the vote belongs to the identity, the customer id is
    13	/// recorded beside it for Kermit.
    14	/// </summary>
    15	public static class RoadmapEndpoints
    16	{
    17	    private const string Unavailable = "The roadmap is not available for this account.";
    18	
    19	    public static IEndpointRouteBuilder MapRoadmapEndpoints(this IEndpointRouteBuilder endpoints)
    20	    {
    21	        endpoints.MapGet("/roadmap", async (
    22	                HttpContext context,
    23	                PortalAccessStore access,
    24	                RoadmapService roadmap,
    25	                CancellationToken cancellationToken) =>
    26	            {
    27	                context.Response.Headers.CacheControl = "no-store";
    28	                var caller = await ResolveAsync(context, access, cancellationToken);
    29	                if (caller is null)
    30	                {
    31	                    return Forbidden();
    32	                }
    33	
    34	                return Results.Json(await roadmap.ListAsync(caller, cancellationToken));
    35	            });
    36	
    37	        endpoints.MapGet("/roadmap/{id}", async (
    38	                HttpContext context,
    39	                PortalAccessStore access,
    40	                RoadmapService roadmap,
    41	                string id,
    42	                CancellationToken cancellationToken) =>
    43	            {
    44	                context.Response.Headers.CacheControl = "no-store";
    45	                var caller = await ResolveAsync(context, access, cancellationToken);
    46	                if (caller is null)
    47	                {
    48	                    return Forbidden();
    49	                }
    50	
    51	                var detail = await roadmap.GetAsync(id, caller, cancellationToken);
    52	                return detail is null ? NotFound() : Results.Json(detail);
    53	            });
    54	
    55	        endpoints.MapPut("/roadmap/{id}/vote", async (
    56	                HttpContext context,
    57	                PortalAccessStore access,
    58	                RoadmapService roadmap,
    59	                string id,
    60	                CancellationToken cancellationToken) =>
    61	            {
    62	                context.Response.Headers.CacheControl = "no-store";
    63	                var caller = await ResolveAsync(context, access, cancellationToken);
    64	                if (caller is null)
    65	                {
    66	                    return Forbidden();
    67	                }
    68	
    69	                return ToResult(await roadmap.VoteAsync(id, caller, cancellationToken), StatusCodes.Status200OK);
    70	            })
    71	            .RequireRateLimiting("roadmap-write");
    72	
    73	        endpoints.MapDelete("/roadmap/{id}/vote", async (
    74	                HttpContext context,
    75	                PortalAccessStore access,
    76	                RoadmapService roadmap,
    77	                string id,
    78	                CancellationToken cancellationToken) =>
    79	            {
    80	                context.Response.Headers.CacheControl = "no-store";
    81	                var caller = await ResolveAsync(context, access, cancellationToken);
    82	                if (caller is null)
    83	                {
    84	                    return Forbidden();
    85	                }
    86	
    87	                return ToResult(await roadmap.UnvoteAsync(id, caller, cancellationToken), StatusCodes.Status200OK);
    88	            })
    89	            .RequireRateLimiting("roadmap-write");
    90	
    91	        endpoints.MapPost("/roadmap/suggestions", async (
    92	                HttpContext context,
    93	                PortalAccessStore access,
    94	                PortalCustomerDirectory customers,
    95	                RoadmapService roadmap,
    96	                PortalRoadmapSuggestionRequest request,
    97	                CancellationToken cancellationToken) =>
    98	            {
    99	                context.Response.Headers.CacheControl = "no-store";
   100	                var caller = await ResolveAsync(context, access, cancellationToken);
   101	                if (caller is null)
   102	                {
   103	                    return Forbidden();
   104	                }
   105	
   106	                var author = await AuthorAsync(context.User, caller, customers, cancellationToken);
   107	                return ToResult(
   108	                    await roadmap.SuggestAsync(request, caller, author, cancellationToken),
   109	                    StatusCodes.Status201Created);
   110	            })
   111	            .RequireRateLimiting("roadmap-write");
   112	
   113	        endpoints.MapPost("/roadmap/{id}/comments", async (
   114	                HttpContext context,
   115	                PortalAccessStore access,
   116	                PortalCustomerDirectory customers,
   117	                RoadmapService roadmap,
   118	                string id,
   119	                PortalRoadmapCommentRequest request,
   120	                CancellationToken cancellationToken) =>
   121	            {
   122	                context.Response.Headers.CacheControl = "no-store";
   123	                var caller = await ResolveAsync(context, access, cancellationToken);
   124	                if (caller is null)
   125	                {
   126	                    return Forbidden();
   127	                }
   128	
   129	                var author = await AuthorAsync(context.User, caller, customers, cancellationToken);
   130	                return ToResult(
   131	                    await roadmap.CommentAsync(id, request, caller, author, cancellationToken),
   132	                    StatusCodes.Status201Created);
   133	            })
   134	            .RequireRateLimiting("roadmap-write");
   135	
   136	        return endpoints;
   137	    }
   138	
   139	    // Same strict resolution as billing and users: the caller names the
   140	    // profile with the opaque service id it already holds; absent,
   141	    // malformed, and unowned ids all answer with one constant 403.
   142	    private static async Task<RoadmapCaller?> ResolveAsync(
   143	        HttpContext context,
   144	        PortalAccessStore access,
   145	        CancellationToken cancellationToken)
   146	    {
   147	        var identity = PortalIdentity.FromPrincipal(context.User);
   148	        if (identity is null)
   149	        {
   150	            return null;
   151	        }
   152	
   153	        var assignment = BillingEndpoints.ResolveAssignment(
   154	            await access.GetAssignmentsAsync(context.User, cancellationToken),
   155	            PortalServiceHeader.Read(context.Request));
   156	        return assignment is null ? null : new RoadmapCaller(identity, assignment.CustomerId);
   157	    }
   158	
   159	    private static async Task<RoadmapAuthor> AuthorAsync(
   160	        ClaimsPrincipal user,
   161	        RoadmapCaller caller,
   162	        PortalCustomerDirectory customers,
   163	        CancellationToken cancellationToken) =>
   164	        new(
   165	            RoadmapValidation.DisplayName(user.FindFirstValue("name")),
   166	            await customers.GetCompanyAsync(caller.CustomerId, cancellationToken));
   167	
   168	    private static IResult ToResult<T>(RoadmapResult<T> result, int successStatus)
   169	        where T : class =>
   170	        result.Error switch
   171	        {
   172	            RoadmapError.None => Results.Json(result.Value, statusCode: successStatus),
   173	            RoadmapError.NotFound => NotFound(),
   174	            RoadmapError.Shipped => Error("shipped", "This has shipped."),
   175	            RoadmapError.InvalidTitle => Error(
   176	                "invalid-title",
   177	                $"Enter a title between {RoadmapValidation.TitleMin} and {RoadmapValidation.TitleMax} characters."),
   178	            RoadmapError.InvalidArea => Error("invalid-area", "Choose an area from the list."),
   179	            RoadmapError.InvalidDescription => Error(
   180	                "invalid-description",
   181	                $"Describe the idea in up to {RoadmapValidation.DescriptionMax} characters."),
   182	            RoadmapError.InvalidText => Error(
   183	                "invalid-text",
   184	                $"Write a comment of up to {RoadmapValidation.CommentMax} characters."),
   185	            _ => throw new InvalidOperationException($"Unhandled roadmap error {result.Error}.")
   186	        };
   187	
   188	    private static IResult Error(string code, string message) =>
   189	        Results.Json(new { code, error = message }, statusCode: StatusCodes.Status400BadRequest);
   190	
   191	    private static IResult NotFound() =>
   192	        Results.Json(
   193	            new { code = "not-found", error = "This roadmap item doesn't exist or is no longer available." },
   194	            statusCode: StatusCodes.Status404NotFound);
   195	
   196	    private static IResult Forbidden() =>
   197	        Results.Problem(statusCode: StatusCodes.Status403Forbidden, title: Unavailable);
   198	}
