     1	using System.Text;
     2	using System.Text.RegularExpressions;
     3	
     4	namespace MaesterCloud.Portal.Services;
     5	
     6	/// <summary>
     7	/// The customer-side input rules of the roadmap. Title, description and
     8	/// comment limits and the text clean-up are the ones Kermit applies to
     9	/// operator edits. Customers never type a summary: the portal derives one
    10	/// from the description, shorter than the 200 characters Kermit allows an
    11	/// operator to write.
    12	/// </summary>
    13	public static partial class RoadmapValidation
    14	{
    15	    public const int TitleMin = 5;
    16	    public const int TitleMax = 90;
    17	    public const int GeneratedSummaryMax = 160;
    18	    public const int DescriptionMax = 4000;
    19	    public const int CommentMax = 2000;
    20	    public const int DisplayNameMax = 100;
    21	    public const string FallbackDisplayName = "Maester Cloud customer";
    22	
    23	    public static readonly IReadOnlyList<string> Areas =
    24	    [
    25	        "Runner", "Portal", "Reports", "Tenants", "Settings", "Setup", "Integrations", "Hosted", "Other"
    26	    ];
    27	
    28	    // Ids are "f-"/"s-" plus hex when minted by the planes; the shape check
    29	    // keeps anything else (and any table-key metacharacter) away from storage.
    30	    [GeneratedRegex("^[fs]-[a-z0-9-]{1,64}$")]
    31	    private static partial Regex PostIdShape();
    32	
    33	    [GeneratedRegex(@"\s+")]
    34	    private static partial Regex Whitespace();
    35	
    36	    public static bool IsPostId(string? id) => id is not null && PostIdShape().IsMatch(id);
    37	
    38	    /// <summary>Trimmed single-line title, or null when outside 5..90 characters.</summary>
    39	    public static string? NormalizeTitle(string? title)
    40	    {
    41	        if (string.IsNullOrWhiteSpace(title))
    42	        {
    43	            return null;
    44	        }
    45	
    46	        var normalized = Whitespace().Replace(title.Trim(), " ");
    47	        return normalized.Length is >= TitleMin and <= TitleMax ? normalized : null;
    48	    }
    49	
    50	    /// <summary>The exact area string, or null for anything not on the list.</summary>
    51	    public static string? NormalizeArea(string? area) =>
    52	        area is null ? null : Areas.FirstOrDefault(known => string.Equals(known, area.Trim(), StringComparison.Ordinal));
    53	
    54	    /// <summary>Newline-normalized, trimmed description; null when empty or over 4000.</summary>
    55	    public static string? NormalizeDescription(string? description) => NormalizeMultiline(description, DescriptionMax);
    56	
    57	    /// <summary>Newline-normalized, trimmed comment text; null when empty or over 2000.</summary>
    58	    public static string? NormalizeCommentText(string? text) => NormalizeMultiline(text, CommentMax);
    59	
    60	    /// <summary>
    61	    /// The card sentence: the description's first paragraph (up to the first
    62	    /// blank line), heading and bullet markers dropped, whitespace collapsed,
    63	    /// cut to 160 characters with an ellipsis.
    64	    /// </summary>
    65	    public static string Summarize(string description)
    66	    {
    67	        var lines = new List<string>();
    68	        foreach (var raw in description.Replace("\r\n", "\n", StringComparison.Ordinal).Split('\n'))
    69	        {
    70	            var line = raw.Trim();
    71	            if (line.Length == 0)
    72	            {
    73	                if (lines.Count > 0)
    74	                {
    75	                    break;
    76	                }
    77	
    78	                continue;
    79	            }
    80	
    81	            if (line.StartsWith("## ", StringComparison.Ordinal))
    82	            {
    83	                line = line[3..];
    84	            }
    85	            else if (line.StartsWith("- ", StringComparison.Ordinal))
    86	            {
    87	                line = line[2..];
    88	            }
    89	
    90	            lines.Add(line);
    91	        }
    92	
    93	        var paragraph = Whitespace().Replace(string.Join(' ', lines), " ").Trim();
    94	        return paragraph.Length <= GeneratedSummaryMax
    95	            ? paragraph
    96	            : string.Concat(paragraph[..(GeneratedSummaryMax - 1)].TrimEnd(), "…");
    97	    }
    98	
    99	    /// <summary>The token's display name, or the generic label when it has none.</summary>
   100	    public static string DisplayName(string? name)
   101	    {
   102	        if (string.IsNullOrWhiteSpace(name))
   103	        {
   104	            return FallbackDisplayName;
   105	        }
   106	
   107	        var normalized = Whitespace().Replace(name.Trim(), " ");
   108	        return normalized.Length <= DisplayNameMax ? normalized : normalized[..DisplayNameMax].TrimEnd();
   109	    }
   110	
   111	    private static string? NormalizeMultiline(string? value, int max)
   112	    {
   113	        if (string.IsNullOrWhiteSpace(value))
   114	        {
   115	            return null;
   116	        }
   117	
   118	        var builder = new StringBuilder(value.Length);
   119	        foreach (var character in value.Replace("\r\n", "\n", StringComparison.Ordinal).Replace('\r', '\n'))
   120	        {
   121	            // Keep newlines and tabs; drop other control characters.
   122	            if (character == '\n' || character == '\t' || !char.IsControl(character))
   123	            {
   124	                builder.Append(character);
   125	            }
   126	        }
   127	
   128	        var normalized = builder.ToString().Trim();
   129	        return normalized.Length is >= 1 && normalized.Length <= max ? normalized : null;
   130	    }
   131	}

     1	using System.Net;
     2	using System.Text.Json;
     3	using MaesterCloud.SignupApi.Services;
     4	using Microsoft.Azure.Functions.Worker;
     5	using Microsoft.Azure.Functions.Worker.Http;
     6	
     7	namespace MaesterCloud.SignupApi.Functions;
     8	
     9	/// <summary>
    10	/// The public roadmap at maester.cloud/roadmap. Anonymous and read-only:
    11	/// voting, suggesting and commenting happen in the signed-in portal.
    12	/// </summary>
    13	public sealed class RoadmapFunctions(IRoadmapReader roadmap)
    14	{
    15	    public const string CacheControl = "public, max-age=60, s-maxage=60";
    16	
    17	    private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);
    18	
    19	    [Function(nameof(GetRoadmap))]
    20	    public async Task<HttpResponseData> GetRoadmap(
    21	        [HttpTrigger(AuthorizationLevel.Anonymous, "get", Route = "roadmap")] HttpRequestData request,
    22	        CancellationToken cancellationToken)
    23	    {
    24	        var snapshot = await roadmap.ReadPublicAsync(cancellationToken);
    25	        var response = await Json(request, HttpStatusCode.OK, snapshot, cancellationToken);
    26	        response.Headers.Add("Cache-Control", CacheControl);
    27	        return response;
    28	    }
    29	
    30	    private static async Task<HttpResponseData> Json<T>(
