/// <summary>
/// One feature on the public roadmap. This record IS the public contract:
/// anything not listed here (authors, keys, customer ids, descriptions,
/// suggestions, comments, operator names) never leaves the private side.
/// </summary>
public sealed record PublicRoadmapFeature(
    string Id,
    string Title,
    string Summary,
    string Area,
    string Status,
    int Progress,
    string Release,
    DateTimeOffset? ShippedAt,
    int Votes,
    int Suggestions);

public sealed record RoadmapSnapshot(
    IReadOnlyList<PublicRoadmapFeature> Features,
    DateTimeOffset GeneratedAt)
{
    private static readonly HashSet<string> PublicStatuses = new(StringComparer.Ordinal)
    {
        RoadmapColumns.StatusPlanned,
        RoadmapColumns.StatusProgress,
        RoadmapColumns.StatusDone
    };

    /// <summary>
    /// Projects raw RoadmapPosts rows to the public shape. A feature's votes
    /// are the VoteCount its row carries: the UNIQUE voters across the feature
    /// and every suggestion linked to it, hidden suggestions included, kept
    /// up to date by the portal (votes) and Kermit (links). "suggestions"
    /// counts only the visible linked ones.
    /// </summary>
    public static RoadmapSnapshot Create(IEnumerable<TableEntity> posts, DateTimeOffset generatedAt)
    {
        var rows = posts
            .Where(post => post.PartitionKey == RoadmapColumns.PostsPartition && !string.IsNullOrEmpty(post.RowKey))
            .ToArray();
        var suggestionsByFeature = rows
            .Where(post => Text(post, RoadmapColumns.Kind) == RoadmapColumns.KindSuggestion)
            .Where(post => Text(post, RoadmapColumns.LinkedFeatureId).Length > 0)
            .ToLookup(post => Text(post, RoadmapColumns.LinkedFeatureId), StringComparer.Ordinal);

        var features = new List<PublicRoadmapFeature>();
        foreach (var post in rows)
        {
            var status = Text(post, RoadmapColumns.Status);
            if (Text(post, RoadmapColumns.Kind) != RoadmapColumns.KindFeature ||
                Flag(post, RoadmapColumns.Hidden) ||
                !PublicStatuses.Contains(status))
            {
                continue;
            }

            features.Add(new PublicRoadmapFeature(
                post.RowKey,
                Text(post, RoadmapColumns.Title),
                Text(post, RoadmapColumns.Summary),
                Text(post, RoadmapColumns.Area),
                status,
                Math.Clamp(Number(post, RoadmapColumns.Progress), 0, 100),
                Text(post, RoadmapColumns.Release),
                Moment(post, RoadmapColumns.ShippedAt),
                Math.Max(0, Number(post, RoadmapColumns.VoteCount)),
                suggestionsByFeature[post.RowKey].Count(suggestion => !Flag(suggestion, RoadmapColumns.Hidden))));
        }

        return new RoadmapSnapshot(
            features
                .OrderByDescending(feature => feature.Votes)
                .ThenBy(feature => feature.Title, StringComparer.OrdinalIgnoreCase)
                .ThenBy(feature => feature.Id, StringComparer.Ordinal)
                .ToArray(),
            generatedAt);

/// The customer's view of the roadmap. Features come from Kermit; customers
/// add suggestions, votes and comments. Hidden posts do not exist here.
///
/// The vote tally is the one every plane agrees on: a suggestion counts its
/// own voters; a feature counts the UNIQUE voters across itself and every
/// suggestion linked to it (hidden or not), so a customer who voted for a
/// suggestion and later for the feature it was merged into is one vote.
///
/// Tallies live on the post rows. A request reads the posts partition and the
/// caller's own vote partition and nothing else; a vote or a comment recounts
/// only the posts it touched and writes the new number back. No request scans
/// the votes or comments table.
/// </summary>
public sealed class RoadmapService(IRoadmapStore store, IPortalAuditSink audit)
{
    public const string SuggestedStatus = "suggested";
    public const string TeamName = "Maester team";
    public const string CustomerActor = "customer";

