    public async Task<RoadmapResult<PortalRoadmapPost>> VoteAsync(
        string id,
        RoadmapCaller caller,
        CancellationToken cancellationToken)
    {
        if (!RoadmapValidation.IsPostId(id))
        {
            return RoadmapResult<PortalRoadmapPost>.Fail(RoadmapError.NotFound);
        }

        var board = await LoadAsync(caller, cancellationToken);
        var post = board.FindVisible(id);
        if (post is null)
        {
            return RoadmapResult<PortalRoadmapPost>.Fail(RoadmapError.NotFound);
        }

        if (board.IsShipped(post))
        {
            return RoadmapResult<PortalRoadmapPost>.Fail(RoadmapError.Shipped);
        }

        if (await store.AddVoteAsync(post.Id, caller.VoterKey, caller.CustomerId, DateTimeOffset.UtcNow, cancellationToken))
        {
            await audit.WriteAsync(caller.CustomerId, caller.Identity, "roadmap-vote-added", new { postId = post.Id }, cancellationToken);
            await RecountVotesAsync(board, board.TallyHolders(post), cancellationToken);
        }

        board.MarkVoted(post.Id);
        return RoadmapResult<PortalRoadmapPost>.Ok(board.Project(post));
    }

    public async Task<RoadmapResult<PortalRoadmapPost>> UnvoteAsync(
        string id,
        RoadmapCaller caller,
        CancellationToken cancellationToken)
    {
        if (!RoadmapValidation.IsPostId(id))
        {
            return RoadmapResult<PortalRoadmapPost>.Fail(RoadmapError.NotFound);
        }

        var board = await LoadAsync(caller, cancellationToken);
        var post = board.FindVisible(id);
        if (post is null)
        {
            return RoadmapResult<PortalRoadmapPost>.Fail(RoadmapError.NotFound);
        }

        // One vote per feature: taking it back also takes back the votes the
        // caller cast on suggestions merged into it, or the tally would keep
        // counting them.
        var targets = new List<string> { post.Id };
        if (post.IsFeature)
        {
            targets.AddRange(board.LinkedSuggestionIds(post.Id).Where(board.HasVoted));
        }

        var removed = false;
        foreach (var target in targets)
        {
            removed |= await store.DeleteVoteAsync(target, caller.VoterKey, cancellationToken);
            board.MarkUnvoted(target);
        }

        if (removed)
        {
            await audit.WriteAsync(caller.CustomerId, caller.Identity, "roadmap-vote-removed", new { postId = post.Id }, cancellationToken);
            await RecountVotesAsync(board, targets.Concat(board.TallyHolders(post)), cancellationToken);
        }

        return RoadmapResult<PortalRoadmapPost>.Ok(board.Project(post));
    }

    public async Task<RoadmapResult<PortalRoadmapPost>> SuggestAsync(
        PortalRoadmapSuggestionRequest request,
        RoadmapCaller caller,
        RoadmapAuthor author,
        CancellationToken cancellationToken)
    {
        var title = RoadmapValidation.NormalizeTitle(request.Title);
        if (title is null)
        {
            return RoadmapResult<PortalRoadmapPost>.Fail(RoadmapError.InvalidTitle);
        }

        var area = RoadmapValidation.NormalizeArea(request.Area);
        if (area is null)
        {
            return RoadmapResult<PortalRoadmapPost>.Fail(RoadmapError.InvalidArea);
        }

        var description = RoadmapValidation.NormalizeDescription(request.Description);
        if (description is null)
        {
            return RoadmapResult<PortalRoadmapPost>.Fail(RoadmapError.InvalidDescription);
        }

        var now = DateTimeOffset.UtcNow;
        var post = new RoadmapPostRecord
        {
            Id = $"s-{Guid.NewGuid().ToString("N")[..12]}",
            Kind = C.KindSuggestion,
            Title = title,
            Summary = RoadmapValidation.Summarize(description),
            Description = description,
            Area = area,
            Status = "",
            Progress = 0,
            Release = "",
            ShippedAt = null,
            Hidden = false,
            LinkedFeatureId = "",
            AuthorName = RoadmapValidation.DisplayName(author.Name),
            AuthorCompany = author.Company?.Trim() ?? "",
            AuthorKey = caller.VoterKey,
            AuthorCustomerId = caller.CustomerId,
            EditedByTeam = false,
            CreatedAt = now,
            UpdatedAt = now,
            UpdatedBy = CustomerActor,
            // The author's own vote, written just below.
            VoteCount = 1,
            CommentCount = 0
        };
        await store.AddPostAsync(post, cancellationToken);
        await store.AddVoteAsync(post.Id, caller.VoterKey, caller.CustomerId, now, cancellationToken);
        await audit.WriteAsync(caller.CustomerId, caller.Identity, "roadmap-suggestion-posted", new { postId = post.Id }, cancellationToken);

        var board = new Board([post], new HashSet<string>(StringComparer.Ordinal) { post.Id });
        return RoadmapResult<PortalRoadmapPost>.Ok(board.Project(post));
    }

