namespace MaesterCloud.Kermit.Endpoints;

/// <summary>
/// The one gate every operator endpoint passes. First the platform's sign-in
/// must be confirmed live (<see cref="PlatformAuthGate"/>), or the call answers
/// 503: without it the principal header could come from anyone. Then the
/// header (or DevMode) resolves to an <see cref="OperatorPrincipal"/> stored
/// on the request, or the call answers 401 with the same JSON body the SPA
/// has always redirected on.
/// </summary>
public static class OpsApi
{
    public const string Prefix = "/api/ops";

    public static RouteGroupBuilder MapOpsApi(this IEndpointRouteBuilder endpoints)
    {
        var group = endpoints.MapGroup(Prefix);
        group.AddEndpointFilter(async (context, next) =>
            await AuthorizeAsync(context.HttpContext) ?? await next(context));

        group.MapSessionEndpoints();
        group.MapOverviewEndpoints();
        group.MapCustomerEndpoints();
        group.MapCustomerDomainEndpoints();
        group.MapSupportEndpoints();
        group.MapCostEndpoints();
        group.MapWaitlistEndpoints();
        group.MapActivityEndpoints();
        group.MapAnnouncementEndpoints();
        group.MapEmailLogEndpoints();
        group.MapOnboardingEndpoints();
        group.MapQuoteEndpoints();
        group.MapRoadmapEndpoints();
        group.MapMethods(
            "/{**path}",
            ["GET", "HEAD", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"],
            () => Results.Json(new { error = "Not found." }, statusCode: StatusCodes.Status404NotFound));
        return group;
    }

    /// <summary>
    /// Null when the caller is an operator (the principal is then stored on
    /// the request); otherwise the response to send instead.
    /// </summary>
    internal static async Task<IResult?> AuthorizeAsync(HttpContext http)
    {
        http.Response.Headers.CacheControl = "no-store";
        var logger = http.RequestServices.GetRequiredService<ILoggerFactory>().CreateLogger("MaesterCloud.Kermit.Auth");
        var platform = await http.RequestServices.GetRequiredService<PlatformAuthGate>().CheckAsync(http.RequestAborted);
        if (!platform.Enforced)
        {
            // The reason goes to the log, not to a caller who may be
            // anonymous precisely because sign-in is off.
            Log.PlatformAuthUnconfirmed(logger, http.Request.Path, platform.Reason ?? "unknown");
            return Results.Json(
                new { error = "Kermit cannot confirm platform sign-in, so it is refusing all operator requests." },
                statusCode: StatusCodes.Status503ServiceUnavailable);
        }
