namespace MaesterCloud.Portal.Security;

public static class PortalOriginValidationExtensions
{
    private static readonly HashSet<string> SafeMethods =
        new(StringComparer.OrdinalIgnoreCase) { "GET", "HEAD", "OPTIONS" };

    public static IApplicationBuilder UsePortalOriginValidation(this IApplicationBuilder app) =>
        app.Use(async (context, next) =>
        {
            // The unsubscribe POST is authorized by its token's per-member
            // secret alone and reads no ambient credential (the portal has no
            // cookies), so an Origin check protects nothing there - and would
            // refuse the RFC 8058 one-click POST a mailbox provider sends,
            // which has none.
            // The custom-domain verify POST is the same shape of exemption: it
            // is anonymous, polled cross-origin by the setup app, and publishes
            // a record only after the target proves it holds the certificate.
            // Exact paths only: nothing else under /api/portal is exempt.
            if (SafeMethods.Contains(context.Request.Method) ||
                !context.Request.Path.StartsWithSegments("/api/portal") ||
                context.Request.Path.Equals(
                    Endpoints.ReleaseEmailEndpoints.UnsubscribePath,
                    StringComparison.OrdinalIgnoreCase) ||
                Endpoints.CustomerDomainEndpoints.IsAnonymousVerifyPath(context.Request.Path))
            {
                await next();
                return;
            }

            var origin = context.Request.Headers.Origin.ToString();
            var configuredOrigin = context.RequestServices
                .GetRequiredService<IConfiguration>()["Portal:PublicOrigin"];
            var expected = string.IsNullOrWhiteSpace(configuredOrigin)
                ? $"{context.Request.Scheme}://{context.Request.Host}"
                : configuredOrigin.TrimEnd('/');
            if (string.IsNullOrWhiteSpace(origin) ||
                !string.Equals(origin, expected, StringComparison.OrdinalIgnoreCase))
            {
                context.Response.StatusCode = StatusCodes.Status403Forbidden;
                await context.Response.WriteAsJsonAsync(new { error = "Request origin is not allowed." });
                return;
            }

            await next();
        });
}

