public static class BillingProviders
{
    public const string Polar = "Polar";

    public const string AzureMarketplace = "AzureMarketplace";

    /// <summary>
    /// Paid on a quote by bank transfer; we are the seller of record. The
    /// row is written by the quote settlement pass, never by a webhook, and
    /// renews by a fresh quote rather than a stored card.
    /// </summary>
    public const string Invoice = "Invoice";

    /// <summary>Row-key prefix for marketplace customers; see CustomerEntity.RowKey.</summary>
    public const string MarketplaceRowKeyPrefix = "mp_";

    /// <summary>Row-key prefix for invoiced customers: "inv_" plus the first paid quote's id.</summary>
    public const string InvoiceRowKeyPrefix = "inv_";

    public static string Of(string? billingProvider) =>
        string.IsNullOrWhiteSpace(billingProvider) ? Polar : billingProvider;

    public static bool IsMarketplace(string? billingProvider) =>
        string.Equals(Of(billingProvider), AzureMarketplace, StringComparison.Ordinal);

    public static bool IsInvoice(string? billingProvider) =>
        string.Equals(Of(billingProvider), Invoice, StringComparison.Ordinal);

    public static string MarketplaceRowKey(string marketplaceSubscriptionId) =>
        MarketplaceRowKeyPrefix + marketplaceSubscriptionId;

    public static string InvoiceRowKey(string quoteId) => InvoiceRowKeyPrefix + quoteId;

    /// <summary>
    /// Whether this row may stand behind someone's email: the sign-up
    /// eligibility gate (<see cref="CustomerStore.ContainsEmailAsync"/>) and
    /// the portal's auto-link both treat a matching row as proof of purchase.
    ///
    /// A marketplace row counts only while Microsoft is billing it
    /// (Subscribed) or holding it through dunning (Suspended, which only an
    /// activated subscription can reach). The hourly reconcile also writes
    /// PendingFulfillmentStart rows, so an operator can see abandoned
    /// purchases - Microsoft has not billed those, and a pending row that
    /// times out becomes Unsubscribed without ever having been activated, so
    /// neither may grant anything. An invoiced row counts while its term is
    /// running or in the renewal grace period (active, past_due) and stops
    /// once the renewal lapses to canceled. Polar rows are unchanged. Any
    /// other provider value is unknown and fails closed.
    ///
    /// portal-api restates this rule (PortalCustomerDirectory) because the two
    /// planes share no code; PortalApi.Tests pins the status strings.
    /// </summary>
    public static bool GrantsEmailEntitlement(string? billingProvider, string? marketplaceStatus, string? subscriptionStatus = null) =>
        Of(billingProvider) switch
        {
            Polar => true,
            AzureMarketplace => marketplaceStatus is
                MarketplaceSubscriptionStatus.Subscribed or MarketplaceSubscriptionStatus.Suspended,
            Invoice => subscriptionStatus is InvoiceActive or InvoicePastDue,
            _ => false
        };

    /// <summary>SubscriptionStatus values an invoiced row may carry and still grant; PortalApi.Tests pins them.</summary>
    public const string InvoiceActive = "active";

    public const string InvoicePastDue = "past_due";
}

