import { defineCollection, reference } from 'astro:content';
import { file, glob } from 'astro/loaders';
import { z } from 'astro/zod';

/**
 * Customer-facing release notes, one Markdown file per release tag
 * (app/content/releases/<tag>.md). These are hand-written on purpose: the
 * internal GitHub release notes are generated from PR titles and never leave
 * the internal repo. publish-customer.yml reuses a file's body as the customer
 * GitHub release notes, so write it for customers and link with absolute URLs.
 */
const releases = defineCollection({
  loader: glob({
    pattern: '*.md',
    base: './app/content/releases',
    // Keep the tag as the id. The default slugger drops dots (v0.6.37 -> v0637).
    generateId: ({ entry }) => entry.replace(/\.md$/, ''),
  }),
  schema: z.object({
    version: z.string().regex(/^v\d+\.\d+\.\d+(-[0-9A-Za-z.-]+)?$/, 'version must be a release tag like v0.6.37'),
    // YAML turns an unquoted 2026-09-22 into a Date; accept either form.
    date: z.coerce.date(),
    title: z.string().optional(),
    summary: z.string().min(1).max(280),
  }),
});

/**
 * Blog authors, one entry per person in app/content/authors.json. A post
 * names its authors by id, so a typo fails the build instead of rendering an
 * anonymous byline.
 */
import type { APIRoute } from 'astro';
import { getReleases, releaseDate, releasePath } from '../lib/releases';

/**
 * Machine-readable release list, emitted as dist/releases.json at build time.
 * Deployed instances poll https://maester.cloud/releases.json for their update
 * check, so the shape is a contract: add fields, never rename or remove them.
 * CORS for this path is set in public/staticwebapp.config.json.
 */
export const GET: APIRoute = async ({ site }) => {
  const origin = site ?? new URL('https://maester.cloud');
  const releases = (await getReleases()).map((entry) => ({
    version: entry.data.version,
    date: releaseDate(entry),
    url: new URL(releasePath(entry.data.version), origin).toString(),
    summary: entry.data.summary,
  }));

  const body = { latest: releases[0] ?? null, releases };
  return new Response(`${JSON.stringify(body, null, 2)}\n`, {
    headers: { 'Content-Type': 'application/json; charset=utf-8' },
  });
};
