// Sign-in for publishers and admins: Better Auth with GitHub as the only provider, stored in the same D1 database.
// Better Auth owns the user, session, account and verification tables (schema.sql). The session cookie is host-only
// (no Domain attribute), so it is sent to packs.maester.cloud alone and never to the rest of maester.cloud.
import { betterAuth } from 'better-auth';
import type { Env } from './index';

export type Auth = ReturnType<typeof createAuth>;

export function createAuth(env: Env, request: Request) {
  const origin = new URL(request.url).origin;
  return betterAuth({
    appName: 'Maester Packs',
    baseURL: env.SITE_URL || origin,
    basePath: '/api/auth',
    secret: env.BETTER_AUTH_SECRET,
    database: env.DB,
    trustedOrigins: [env.SITE_URL || origin],
    telemetry: { enabled: false },
    socialProviders: {
      github: {
        clientId: env.GITHUB_CLIENT_ID,
        clientSecret: env.GITHUB_CLIENT_SECRET,
        // Added to Better Auth's read:user and user:email: read:org lists the organisations a publisher belongs to, so they
        // can publish an organisation's repository.
        scope: ['read:org'],
        mapProfileToUser: (profile) => ({ githubLogin: profile.login }),
      },
    },
    user: {
      additionalFields: {
        githubLogin: { type: 'string', required: false, input: false },
      },
    },
    account: {
      encryptOAuthTokens: true,
    },
    session: {
      expiresIn: 60 * 60 * 24 * 14,
      updateAge: 60 * 60 * 24,
    },
    advanced: {
      cookiePrefix: 'packs',
      useSecureCookies: origin.startsWith('https://'),
      defaultCookieAttributes: { sameSite: 'lax', httpOnly: true, path: '/' },
    },
  });
}

export interface Viewer {
  userId: string;
  githubId: number;
  login: string;
  name: string;
  image: string | null;
  admin: boolean;
  accountRowId: string;
}

// The signed-in person, with their GitHub ID and whether they are an admin, or null. Admins are the GitHub IDs in
// ADMIN_GITHUB_IDS (merill by default) plus anyone an admin added on the admin page.
export async function getViewer(auth: Auth, env: Env, request: Request): Promise<Viewer | null> {
  const session = await auth.api.getSession({ headers: request.headers });
  if (!session) return null;
  const row = await env.DB.prepare(`SELECT id, accountId FROM account WHERE userId = ? AND providerId = 'github' LIMIT 1`)
    .bind(session.user.id).first<{ id: string; accountId: string }>();
  if (!row) return null;
  const githubId = Number(row.accountId);
  const user = session.user as typeof session.user & { githubLogin?: string | null };
  return {
    userId: session.user.id,
    githubId,
    login: user.githubLogin || session.user.name,
    name: session.user.name,
    image: session.user.image ?? null,
    admin: await isAdmin(env, githubId),
    accountRowId: row.id,
  };
}

