public sealed class OperatorAuthorizer(OperatorAuthOptions options)
{
    public bool DevMode => options.DevMode;

    public bool TryAuthorize(HttpRequest request, out OperatorPrincipal? principal)
    {
        if (options.DevMode)
        {
            principal = OperatorPrincipal.Development;
            return true;
        }

        principal = null;

        // Fail closed rather than skip checks a deployed ring always sets:
        // without sign-in configured the header could come from anyone, and
        // without a tenant the tid check would silently disappear.
        if (!options.PlatformAuthEnabled || options.TenantId is null)
        {
            return false;
        }

        if (!OperatorPrincipal.TryParse(request.Headers, out principal) || principal is null)
        {
            return false;
        }

        // Only the Microsoft provider is configured on the platform; anything
        // else in the header means a misconfiguration, not an operator.
        if (!string.Equals(principal.IdentityProvider, "aad", StringComparison.Ordinal) ||
            !string.Equals(principal.TenantId, options.TenantId, StringComparison.OrdinalIgnoreCase))
        {
            principal = null;
            return false;
        }

        return true;
    }
}

