        AddAssignment(assignments, entity);
    }

    // An assignment is durable, the entitlement behind it is not: an
    // invoiced customer whose renewal lapsed keeps their seat rows but
    // must lose the portal. Filter here, where every endpoint resolves
    // access, rather than in each of them.
    var entitled = new List<PortalServiceAssignment>();
    var decided = new Dictionary<string, bool>(StringComparer.Ordinal);
    foreach (var assignment in assignments.Values)
    {
        if (!decided.TryGetValue(assignment.CustomerId, out var grants))
        {
            grants = customers is null || await customers.GrantsAccessAsync(assignment.CustomerId, cancellationToken);
            decided[assignment.CustomerId] = grants;
        }

        if (grants)
        {
            entitled.Add(assignment);
        }
    }

    return entitled
        .OrderBy(assignment => assignment.ServiceId, StringComparer.Ordinal)
    }

    var response = await customers.GetEntityIfExistsAsync<TableEntity>(
        "customers",
        customerId,
        select: ["BillingProvider", "MarketplaceStatus", "SubscriptionStatus"],
        cancellationToken: cancellationToken);
    if (!response.HasValue || response.Value is null)
    {
        return true;
    }

    return GrantsEmailEntitlement(
        response.Value.GetString("BillingProvider"),
        response.Value.GetString("MarketplaceStatus"),
        response.Value.GetString("SubscriptionStatus"));
}

public const string PolarBillingProvider = "Polar";

public const string MarketplaceBillingProvider = "AzureMarketplace";

/// <summary>Paid on a quote by bank transfer; the signup API's quote settlement writes the row.</summary>
public const string InvoiceBillingProvider = "Invoice";

/// <summary>SubscriptionStatus values an invoiced row may carry and still grant access.</summary>
public const string InvoiceActive = "active";

public const string InvoicePastDue = "past_due";

/// <summary>Microsoft's status for an activated, billed subscription.</summary>
public const string MarketplaceSubscribed = "Subscribed";

/// <summary>Microsoft's dunning status; only an activated subscription can reach it.</summary>
public const string MarketplaceSuspended = "Suspended";

/// <summary>
/// Whether a customer row may stand behind a verified email for
/// auto-linking. A marketplace row counts only once Microsoft is billing
/// it: the signup API also records PendingFulfillmentStart purchases (and
/// they later lapse to Unsubscribed without ever being activated) so an
/// operator can see them, and neither may hand anyone a portal. An
/// invoiced row counts while its paid year runs or sits in the renewal
/// grace period, and stops once the renewal lapses to canceled. Polar
/// rows are unchanged, and an unrecognised provider fails closed.
///
/// Restates BillingProviders.GrantsEmailEntitlement in the signup API,
/// which gates External ID sign-up the same way; the two planes share no
/// code, so BillingProviderContractTests pins the strings.
/// </summary>
public static bool GrantsEmailEntitlement(string? billingProvider, string? marketplaceStatus, string? subscriptionStatus = null)
{
    var provider = string.IsNullOrWhiteSpace(billingProvider) ? PolarBillingProvider : billingProvider;
    return provider switch
    {
        PolarBillingProvider => true,
        MarketplaceBillingProvider => marketplaceStatus is MarketplaceSubscribed or MarketplaceSuspended,
        InvoiceBillingProvider => subscriptionStatus is InvoiceActive or InvoicePastDue,
        _ => false
    };
}

